insert into public.media_aids (slug,kind,title,description,levels,subject,topic,orient,pages,cover_url,pdf_url,bw_url,page_urls,review_note,status,sort_order) values
('pr-color-shapes','printable','ألوّن الأشكال','ستة أشكال كبيرة غير ملوّنة (دائرة ومربع ومثلث ومستطيل ونجمة وقلب) مع اسم كل شكل، ليلوّنها الطفل بحرية وهو يتعلم أسماءها.',array['a4','a5','a6','g1']::text[],'الرياضيات','الأشكال','portrait',1,'images/media/pr-color-shapes/thumb.webp','files/media/pr-color-shapes.pdf','files/media/pr-color-shapes-bw.pdf',array['images/media/pr-color-shapes/p01.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. وسيلة قابلة للطباعة أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4، وفي آخرها صفحة إجابات للمعلم أو ولي الأمر. لم تُراجَع من جهة تعليمية رسمية.','published',30),
('pr-shadow-match','printable','أصِل الصورة بظلّها','خمس صور حيوانات تقابلها خمسة ظلال بترتيب مختلف، يصل الطفل كل صورة بظلّها الصحيح لتنمية الملاحظة والتمييز البصري، مع صفحة الإجابات.',array['a4','a5','a6','g1']::text[],'المهارات الحياتية','التفكير','portrait',2,'images/media/pr-shadow-match/thumb.webp','files/media/pr-shadow-match.pdf','files/media/pr-shadow-match-bw.pdf',array['images/media/pr-shadow-match/p01.webp','images/media/pr-shadow-match/p02.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. وسيلة قابلة للطباعة أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4، وفي آخرها صفحة إجابات للمعلم أو ولي الأمر. لم تُراجَع من جهة تعليمية رسمية.','published',31),
('pr-cut-paste-sort','printable','أقصّ وألصق: فواكه وحيوانات','نشاط قص ولصق: صفحة فيها صندوقان (فواكه وحيوانات) وصفحة بطاقات للقص، يفرزها الطفل ويلصقها في الصندوق المناسب، مع صفحة الإجابات.',array['a4','a5','a6','g1']::text[],'المهارات الحياتية','التصنيف','portrait',3,'images/media/pr-cut-paste-sort/thumb.webp','files/media/pr-cut-paste-sort.pdf','files/media/pr-cut-paste-sort-bw.pdf',array['images/media/pr-cut-paste-sort/p01.webp','images/media/pr-cut-paste-sort/p02.webp','images/media/pr-cut-paste-sort/p03.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. وسيلة قابلة للطباعة أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4، وفي آخرها صفحة إجابات للمعلم أو ولي الأمر. لم تُراجَع من جهة تعليمية رسمية.','published',32),
('pr-big-small','printable','كبير وصغير','خمسة صفوف في كل صف صورتان متشابهتان إحداهما كبيرة والأخرى صغيرة، يضع الطفل دائرة حول الكبيرة لتعلم مفهوم الحجم، مع صفحة الإجابات.',array['a3','a4','a5','a6']::text[],'الرياضيات','المقارنة','portrait',2,'images/media/pr-big-small/thumb.webp','files/media/pr-big-small.pdf','files/media/pr-big-small-bw.pdf',array['images/media/pr-big-small/p01.webp','images/media/pr-big-small/p02.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. وسيلة قابلة للطباعة أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4، وفي آخرها صفحة إجابات للمعلم أو ولي الأمر. لم تُراجَع من جهة تعليمية رسمية.','published',33),
('pr-trace-letters','printable','أتتبّع الحروف الهجائية','ثلاث ورقات لتتبّع الحروف العربية الثمانية والعشرين: لكل حرف شكل ملوّن وثلاثة حروف رمادية للتتبّع ومربعان فارغان للكتابة، لتدريب اليد قبل الكتابة.',array['a6','g1','g2']::text[],'اللغة العربية','الحروف','portrait',3,'images/media/pr-trace-letters/thumb.webp','files/media/pr-trace-letters.pdf','files/media/pr-trace-letters-bw.pdf',array['images/media/pr-trace-letters/p01.webp','images/media/pr-trace-letters/p02.webp','images/media/pr-trace-letters/p03.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. وسيلة قابلة للطباعة أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4، وفي آخرها صفحة إجابات للمعلم أو ولي الأمر. لم تُراجَع من جهة تعليمية رسمية.','published',34),
('pr-maze-easy','printable','متاهة سهلة للصغار','متاهة كبيرة بسيطة بحجم ٦ × ٨ مربعات بممرات واسعة تناسب الصغار، لها حل واحد، مع صفحة الحل.',array['a4','a5','a6','g1']::text[],'المهارات الحياتية','التفكير','portrait',2,'images/media/pr-maze-easy/thumb.webp','files/media/pr-maze-easy.pdf','files/media/pr-maze-easy-bw.pdf',array['images/media/pr-maze-easy/p01.webp','images/media/pr-maze-easy/p02.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. وسيلة قابلة للطباعة أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4، وفي آخرها صفحة إجابات للمعلم أو ولي الأمر. لم تُراجَع من جهة تعليمية رسمية.','published',35),
('pr-dot-house','printable','وصل النقاط: بيت','ورقة وصل النقاط من ١ إلى ٩ ترسم بيتًا بسقف وباب عند الوصل بالترتيب، للصغار في بدايات العدّ، مع صفحة الشكل النهائي.',array['a4','a5','a6']::text[],'الرياضيات','العدّ','portrait',2,'images/media/pr-dot-house/thumb.webp','files/media/pr-dot-house.pdf','files/media/pr-dot-house-bw.pdf',array['images/media/pr-dot-house/p01.webp','images/media/pr-dot-house/p02.webp']::text[],'محتوى أصلي من إعداد زاد (توليد برمجي)؛ لم يراجعه معلم أو جهة تعليمية بعد. وسيلة قابلة للطباعة أصلية من إعداد زاد، تُطبع بحجم ١٠٠٪ على ورق A4، وفي آخرها صفحة إجابات للمعلم أو ولي الأمر. لم تُراجَع من جهة تعليمية رسمية.','published',36)
